import React, { useState, useEffect, useCallback } from "react";
import * as XLSX from "xlsx";
import {
  Wallet, FileText, Settings, LayoutGrid, Plus, Trash2, Pencil,
  Download, Search, X, Printer, Check, AlertCircle, Loader2, Users, UserPlus
} from "lucide-react";

/* ---------------------------------------------------------------------- */
/*  Assets (logo dell'associazione, incorporati come base64)               */
/* ---------------------------------------------------------------------- */

const LOGO_MARK_B64 = "data:image/png;base64,";
const LOGO_HEADER_B64 = "data:image/jpeg;base64,";

/* ---------------------------------------------------------------------- */
/*  Helpers                                                                */
/* ---------------------------------------------------------------------- */

const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;

const todayISO = () => new Date().toISOString().slice(0, 10);

const fmtDate = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso + "T00:00:00");
  if (isNaN(d)) return iso;
  return d.toLocaleDateString("it-IT", { day: "2-digit", month: "2-digit", year: "numeric" });
};

const fmtCurrency = (n) =>
  new Intl.NumberFormat("it-IT", { style: "currency", currency: "EUR" }).format(Number(n) || 0);

const yearOf = (iso) => (iso ? Number(iso.slice(0, 4)) : new Date().getFullYear());

const lastReceiptNumber = (donazioni) => {
  let max = null;
  donazioni.forEach((d) => {
    const n = parseInt(String(d.numeroRicevuta).replace(/\D+/g, ""), 10);
    if (!isNaN(n) && (max === null || n > max)) max = n;
  });
  return max;
};

const suggestReceiptNumber = (donazioni) => {
  const last = lastReceiptNumber(donazioni);
  return String(last === null ? 1 : last + 1);
};

const emptyDonazione = () => ({
  id: null, data: todayISO(), numeroRicevuta: "", titolo: "Signora", donatoreId: "",
  donatoreNome: "", donatoreIndirizzo: "", donatoreCapComune: "",
  importo: "", metodoPagamento: "Contanti", inMemoriaDi: "", causale: "", note: "",
});

const emptyDonatore = () => ({
  id: null, titolo: "Signora", nome: "", indirizzo: "", capComune: "",
  telefono: "", email: "", note: "",
});

const emptyImpostazioni = () => ({
  nome: "Una Mano Per Vivere ODV-ETS",
  nomeBreve: "Una Mano per Vivere",
  indirizzoSede: "Via Giovanni da Udine, 25",
  capComuneSede: "33053 Latisana (UD)",
  telefono: "0431 520054",
  codiceFiscale: "92009580306",
  runtsNumero: "46228",
  runtsData: "31/08/2022",
  orari: "Lunedì e Venerdì dalle ore 17.00 alle ore 19.00",
  sitoWeb: "www.unamanopervivere.it",
  email: "associazioneunamanopervivere@gmail.com",
  luogoEmissione: "Latisana",
});

/* ---------------------------------------------------------------------- */
/*  Storage — chiamate al backend Express, che le salva su Postgres         */
/* ---------------------------------------------------------------------- */

async function loadKey(key, fallback) {
  try {
    const res = await fetch(`/api/storage/${key}`);
    if (res.status === 404) return fallback;
    if (!res.ok) return fallback;
    const data = await res.json();
    return data.value;
  } catch (e) {
    return fallback;
  }
}

async function saveKey(key, value) {
  try {
    const res = await fetch(`/api/storage/${key}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ value }),
    });
    return res.ok;
  } catch (e) {
    return false;
  }
}

/* ---------------------------------------------------------------------- */
/*  Small UI atoms                                                        */
/* ---------------------------------------------------------------------- */

function Btn({ children, variant = "primary", icon: Icon, ...props }) {
  const base = "btn";
  const cls = variant === "primary" ? "btn-primary" : variant === "ghost" ? "btn-ghost" : variant === "danger" ? "btn-danger" : "btn-outline";
  return (
    <button className={`${base} ${cls}`} {...props}>
      {Icon && <Icon size={15} strokeWidth={2} />}
      {children}
    </button>
  );
}

function Field({ label, children, span }) {
  return (
    <label className={`field ${span ? "field-span" : ""}`}>
      <span className="field-label">{label}</span>
      {children}
    </label>
  );
}

function Modal({ title, onClose, children, wide }) {
  return (
    <div className="modal-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className={`modal ${wide ? "modal-wide" : ""}`}>
        <div className="modal-header">
          <h3>{title}</h3>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="modal-body">{children}</div>
      </div>
    </div>
  );
}

function EmptyState({ icon: Icon, title, hint, action }) {
  return (
    <div className="empty-state">
      <Icon size={28} strokeWidth={1.5} />
      <p className="empty-title">{title}</p>
      <p className="empty-hint">{hint}</p>
      {action}
    </div>
  );
}

function StatCard({ label, value, sub }) {
  return (
    <div className="stat-card">
      <span className="stat-label">{label}</span>
      <span className="stat-value">{value}</span>
      {sub && <span className="stat-sub">{sub}</span>}
    </div>
  );
}

/* ---------------------------------------------------------------------- */
/*  App                                                                    */
/* ---------------------------------------------------------------------- */

export default function App() {
  const [tab, setTab] = useState("dashboard");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);

  const [donazioni, setDonazioni] = useState([]);
  const [donatori, setDonatori] = useState([]);
  const [impostazioni, setImpostazioni] = useState(emptyImpostazioni());

  const [donazioneModal, setDonazioneModal] = useState(null);
  const [donatoreModal, setDonatoreModal] = useState(null);
  const [ricevutaPreview, setRicevutaPreview] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const [donazioniFilter, setDonazioniFilter] = useState("");
  const [donatoriFilter, setDonatoriFilter] = useState("");
  const [annoFiltro, setAnnoFiltro] = useState(new Date().getFullYear());

  useEffect(() => {
    (async () => {
      const [d, don, i] = await Promise.all([
        loadKey("donazioni", []),
        loadKey("donatori", []),
        loadKey("impostazioni", emptyImpostazioni()),
      ]);
      setDonazioni(d);
      setDonatori(don);
      setImpostazioni({ ...emptyImpostazioni(), ...i });
      setLoading(false);
    })();
  }, []);

  const notify = useCallback((msg, isError) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 2600);
  }, []);

  const persistDonazioni = async (next) => {
    setDonazioni(next);
    setSaving(true);
    const ok = await saveKey("donazioni", next);
    setSaving(false);
    if (!ok) notify("Errore nel salvataggio delle donazioni.", true);
    return ok;
  };

  const persistDonatori = async (next) => {
    setDonatori(next);
    setSaving(true);
    const ok = await saveKey("donatori", next);
    setSaving(false);
    if (!ok) notify("Errore nel salvataggio dell'anagrafica donatori.", true);
    return ok;
  };

  const persistImpostazioni = async (next) => {
    setImpostazioni(next);
    setSaving(true);
    const ok = await saveKey("impostazioni", next);
    setSaving(false);
    if (ok) notify("Impostazioni salvate."); else notify("Errore nel salvataggio.", true);
    return ok;
  };

  /* ---------- Donazioni CRUD ---------- */

  const saveDonazione = async (data, salvaInAnagrafica) => {
    const finalData = { ...data, numeroRicevuta: data.numeroRicevuta.trim() || suggestReceiptNumber(donazioni) };
    let next;
    if (finalData.id) {
      next = donazioni.map((d) => (d.id === finalData.id ? finalData : d));
    } else {
      next = [...donazioni, { ...finalData, id: uid() }];
    }
    const ok = await persistDonazioni(next);
    if (!ok) return;

    if (salvaInAnagrafica && finalData.donatoreNome.trim()) {
      const esistente = donatori.find((don) => don.id === finalData.donatoreId);
      const donatoreData = {
        id: esistente ? esistente.id : uid(),
        titolo: finalData.titolo, nome: finalData.donatoreNome,
        indirizzo: finalData.donatoreIndirizzo, capComune: finalData.donatoreCapComune,
        telefono: esistente ? esistente.telefono : "", email: esistente ? esistente.email : "",
        note: esistente ? esistente.note : "",
      };
      const nextDonatori = esistente
        ? donatori.map((don) => (don.id === esistente.id ? donatoreData : don))
        : [...donatori, donatoreData];
      await persistDonatori(nextDonatori);
    }

    setDonazioneModal(null);
    notify(finalData.id ? "Donazione aggiornata." : "Donazione registrata e ricevuta generata.");
  };

  const deleteDonazione = async (id) => {
    const next = donazioni.filter((d) => d.id !== id);
    const ok = await persistDonazioni(next);
    if (ok) { setConfirmDelete(null); notify("Donazione rimossa."); }
  };

  const openNuovaDonazione = (donatoreIniziale) => {
    setDonazioneModal({
      ...emptyDonazione(),
      numeroRicevuta: suggestReceiptNumber(donazioni),
      ...(donatoreIniziale ? {
        donatoreId: donatoreIniziale.id, titolo: donatoreIniziale.titolo, donatoreNome: donatoreIniziale.nome,
        donatoreIndirizzo: donatoreIniziale.indirizzo, donatoreCapComune: donatoreIniziale.capComune,
      } : {}),
    });
  };

  /* ---------- Donatori CRUD ---------- */

  const saveDonatore = async (data) => {
    let next;
    if (data.id) {
      next = donatori.map((don) => (don.id === data.id ? data : don));
    } else {
      next = [...donatori, { ...data, id: uid() }];
    }
    const ok = await persistDonatori(next);
    if (ok) { setDonatoreModal(null); notify(data.id ? "Donatore aggiornato." : "Donatore aggiunto all'anagrafica."); }
  };

  const deleteDonatore = async (id) => {
    const next = donatori.filter((don) => don.id !== id);
    const ok = await persistDonatori(next);
    if (ok) { setConfirmDelete(null); notify("Donatore rimosso dall'anagrafica."); }
  };

  /* ---------- Export ---------- */

  const donazioniRows = () =>
    donazioniAnno
      .slice()
      .sort((a, b) => a.data.localeCompare(b.data))
      .map((d) => ({
        "N. Ricevuta": d.numeroRicevuta, Data: fmtDate(d.data),
        Donatore: d.donatoreNome, Indirizzo: d.donatoreIndirizzo, "Cap/Comune": d.donatoreCapComune,
        "Importo (€)": Number(d.importo) || 0, "In memoria di": d.inMemoriaDi,
        "Metodo di pagamento": d.metodoPagamento, Causale: d.causale, Note: d.note,
      }));

  const exportDonazioniExcel = () => {
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(donazioniRows()), "Donazioni");
    const suffisso = annoFiltro === "tutti" ? "tutti_gli_anni" : annoFiltro;
    XLSX.writeFile(wb, `Registro_Donazioni_${suffisso}_${todayISO()}.xlsx`);
  };

  const donatoriRows = () =>
    donatori.map((don) => ({
      Titolo: don.titolo, "Nome e cognome": don.nome, Indirizzo: don.indirizzo,
      "Cap/Comune": don.capComune, Telefono: don.telefono, Email: don.email, Note: don.note,
    }));

  const exportDonatoriExcel = () => {
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(donatoriRows()), "Donatori");
    XLSX.writeFile(wb, `Anagrafica_Donatori_${todayISO()}.xlsx`);
  };

  const exportTuttoExcel = () => {
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(donazioniRows()), "Donazioni");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(donatoriRows()), "Donatori");
    const totals = Object.entries(
      donazioni.reduce((acc, d) => {
        const y = yearOf(d.data);
        acc[y] = (acc[y] || 0) + (Number(d.importo) || 0);
        return acc;
      }, {})
    ).map(([anno, totale]) => ({ Anno: anno, "Totale donazioni (€)": totale }));
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(totals), "Riepilogo");
    XLSX.writeFile(wb, `Report_Associazione_${todayISO()}.xlsx`);
  };

  /* ---------- Derived ---------- */

  const currentYear = new Date().getFullYear();

  const anniDisponibili = Array.from(new Set([currentYear, ...donazioni.map((d) => yearOf(d.data))]))
    .sort((a, b) => b - a);

  const donazioniAnno = annoFiltro === "tutti" ? donazioni : donazioni.filter((d) => yearOf(d.data) === annoFiltro);

  const totaleAnno = donazioniAnno.reduce((sum, d) => sum + (Number(d.importo) || 0), 0);
  const ricevuteAnno = donazioniAnno.length;
  const ultimeDonazioni = donazioniAnno.slice().sort((a, b) => b.data.localeCompare(a.data)).slice(0, 5);

  const donazioniFiltrate = donazioniAnno.slice().sort((a, b) => b.data.localeCompare(a.data)).filter((d) => {
    const q = donazioniFilter.trim().toLowerCase();
    if (!q) return true;
    return `${d.donatoreNome} ${d.numeroRicevuta} ${d.inMemoriaDi}`.toLowerCase().includes(q);
  });

  const donatoriFiltrati = donatori.slice().sort((a, b) => a.nome.localeCompare(b.nome)).filter((don) => {
    const q = donatoriFilter.trim().toLowerCase();
    if (!q) return true;
    return `${don.nome} ${don.indirizzo} ${don.capComune}`.toLowerCase().includes(q);
  });

  const NAV = [
    { id: "dashboard", label: "Riepilogo", icon: LayoutGrid },
    { id: "donazioni", label: "Donazioni", icon: Wallet },
    { id: "donatori", label: "Donatori", icon: Users },
    { id: "ricevute", label: "Ricevute", icon: FileText },
    { id: "impostazioni", label: "Impostazioni", icon: Settings },
  ];

  if (loading) {
    return (
      <div className="loading-screen">
        <Styles />
        <Loader2 className="spin" size={26} />
        <p>Apertura del registro…</p>
      </div>
    );
  }

  return (
    <div className="app-shell">
      <Styles />
      <aside className="sidebar">
        <div className="brand">
          <img className="brand-mark" src={LOGO_MARK_B64} alt="Logo" />
          <div>
            <div className="brand-name">{impostazioni.nomeBreve || impostazioni.nome}</div>
            <div className="brand-sub">Donazioni &amp; ricevute</div>
          </div>
        </div>
        <div className="year-filter">
          <label className="year-filter-label">Anno di riferimento</label>
          <select className="input" value={annoFiltro} onChange={(e) => setAnnoFiltro(e.target.value === "tutti" ? "tutti" : Number(e.target.value))}>
            <option value="tutti">Tutti gli anni</option>
            {anniDisponibili.map((y) => <option key={y} value={y}>{y}</option>)}
          </select>
        </div>

        <nav className="nav">
          {NAV.map((n) => (
            <button key={n.id} className={`nav-item ${tab === n.id ? "active" : ""}`} onClick={() => setTab(n.id)}>
              <n.icon size={17} strokeWidth={2} />
              {n.label}
            </button>
          ))}
        </nav>
        <div className="sidebar-foot">
          {saving ? <span className="save-indicator"><Loader2 size={12} className="spin" /> salvataggio…</span>
                  : <span className="save-indicator ok"><Check size={12} /> dati sincronizzati</span>}
        </div>
      </aside>

      <main className="main">
        {tab === "dashboard" && (
          <DashboardTab
            impostazioni={impostazioni} annoFiltro={annoFiltro}
            totaleAnno={totaleAnno} ricevuteAnno={ricevuteAnno} ultimeDonazioni={ultimeDonazioni}
            onNuovaDonazione={() => openNuovaDonazione()}
            onExportAll={exportTuttoExcel}
          />
        )}

        {tab === "donazioni" && (
          <DonazioniTab
            donazioni={donazioniFiltrate} totale={donazioniAnno.length} filter={donazioniFilter} setFilter={setDonazioniFilter}
            ultimoNumero={lastReceiptNumber(donazioni)} annoFiltro={annoFiltro}
            onNuova={() => openNuovaDonazione()}
            onModifica={(d) => setDonazioneModal(d)}
            onElimina={(d) => setConfirmDelete({ tipo: "donazione", id: d.id, label: `ricevuta n. ${d.numeroRicevuta}` })}
            onVediRicevuta={(d) => setRicevutaPreview(d)}
            onExport={exportDonazioniExcel}
          />
        )}

        {tab === "donatori" && (
          <DonatoriTab
            donatori={donatoriFiltrati} totale={donatori.length} filter={donatoriFilter} setFilter={setDonatoriFilter}
            onNuovo={() => setDonatoreModal(emptyDonatore())}
            onModifica={(don) => setDonatoreModal(don)}
            onElimina={(don) => setConfirmDelete({ tipo: "donatore", id: don.id, label: don.nome })}
            onNuovaDonazione={(don) => openNuovaDonazione(don)}
            onExport={exportDonatoriExcel}
          />
        )}

        {tab === "ricevute" && (
          <RicevuteTab
            donazioni={donazioniFiltrate} totale={donazioniAnno.length} filter={donazioniFilter} setFilter={setDonazioniFilter}
            annoFiltro={annoFiltro}
            onVedi={(d) => setRicevutaPreview(d)}
            onExport={exportDonazioniExcel}
          />
        )}

        {tab === "impostazioni" && (
          <ImpostazioniTab impostazioni={impostazioni} onSalva={persistImpostazioni} />
        )}
      </main>

      {donazioneModal && (
        <DonazioneForm donazione={donazioneModal} donatori={donatori} donazioni={donazioni} onClose={() => setDonazioneModal(null)} onSave={saveDonazione} />
      )}

      {donatoreModal && (
        <DonatoreForm donatore={donatoreModal} onClose={() => setDonatoreModal(null)} onSave={saveDonatore} />
      )}

      {ricevutaPreview && (
        <RicevutaPreview donazione={ricevutaPreview} impostazioni={impostazioni} onClose={() => setRicevutaPreview(null)} />
      )}

      {confirmDelete && (
        <Modal title="Confermi l'eliminazione?" onClose={() => setConfirmDelete(null)}>
          <p className="confirm-text">
            Stai per eliminare in modo permanente <strong>{confirmDelete.label}</strong>. L'operazione non è reversibile.
          </p>
          <div className="modal-actions">
            <Btn variant="ghost" onClick={() => setConfirmDelete(null)}>Annulla</Btn>
            <Btn variant="danger" icon={Trash2} onClick={() =>
              confirmDelete.tipo === "donatore" ? deleteDonatore(confirmDelete.id) : deleteDonazione(confirmDelete.id)
            }>Elimina definitivamente</Btn>
          </div>
        </Modal>
      )}

      {toast && (
        <div className={`toast ${toast.isError ? "toast-error" : ""}`}>
          {toast.isError ? <AlertCircle size={15} /> : <Check size={15} />}
          {toast.msg}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------------- */
/*  Dashboard                                                              */
/* ---------------------------------------------------------------------- */

function DashboardTab({ impostazioni, annoFiltro, totaleAnno, ricevuteAnno, ultimeDonazioni, onNuovaDonazione, onExportAll }) {
  const etichettaAnno = annoFiltro === "tutti" ? "tutti gli anni" : `anno ${annoFiltro}`;
  return (
    <div className="page">
      <header className="hero">
        <div className="hero-eyebrow">Registro attività — {etichettaAnno}</div>
        <h1>{impostazioni.nome}</h1>
        <p className="hero-sub">
          Un unico registro per donazioni e ricevute: quanto serve al direttivo per tenere i conti in ordine
          e produrre report in un clic.
        </p>
        <div className="hero-actions">
          <Btn icon={Plus} onClick={onNuovaDonazione}>Registra donazione</Btn>
          <Btn variant="ghost" icon={Download} onClick={onExportAll}>Esporta report completo</Btn>
        </div>
      </header>

      <div className="stat-grid">
        <StatCard label={`Donazioni — ${etichettaAnno}`} value={fmtCurrency(totaleAnno)} />
        <StatCard label={`Ricevute emesse — ${etichettaAnno}`} value={ricevuteAnno} />
      </div>

      <section className="panel">
        <div className="panel-head">
          <h2>Ultime donazioni</h2>
        </div>
        {ultimeDonazioni.length === 0 ? (
          <EmptyState icon={Wallet} title="Nessuna donazione registrata" hint="Le donazioni registrate compariranno qui, con la ricevuta generata automaticamente." />
        ) : (
          <table className="ledger-table">
            <thead>
              <tr><th>Ricevuta</th><th>Data</th><th>Donatore</th><th>In memoria di</th><th className="num">Importo</th></tr>
            </thead>
            <tbody>
              {ultimeDonazioni.map((d) => (
                <tr key={d.id}>
                  <td className="mono">n. {d.numeroRicevuta}</td>
                  <td>{fmtDate(d.data)}</td>
                  <td>{d.donatoreNome}</td>
                  <td>{d.inMemoriaDi || "—"}</td>
                  <td className="num mono">{fmtCurrency(d.importo)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>
    </div>
  );
}

/* ---------------------------------------------------------------------- */
/*  Donazioni                                                              */
/* ---------------------------------------------------------------------- */

function DonazioniTab({ donazioni, totale, filter, setFilter, onNuova, onModifica, onElimina, onVediRicevuta, onExport, ultimoNumero, annoFiltro }) {
  const etichettaAnno = annoFiltro === "tutti" ? "tutti gli anni" : annoFiltro;
  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h1>Donazioni <span className="page-title-year">— {etichettaAnno}</span></h1>
          <p className="page-sub">
            {totale} {totale === 1 ? "donazione registrata" : "donazioni registrate"}
            {ultimoNumero !== null && ` · ultima ricevuta n. ${ultimoNumero}`}
          </p>
        </div>
        <div className="page-head-actions">
          <Btn variant="outline" icon={Download} onClick={onExport} disabled={totale === 0}>Esporta Excel</Btn>
          <Btn icon={Plus} onClick={onNuova}>Registra donazione</Btn>
        </div>
      </div>

      <div className="toolbar">
        <div className="search-box">
          <Search size={15} />
          <input placeholder="Cerca per donatore, ricevuta, in memoria di…" value={filter} onChange={(e) => setFilter(e.target.value)} />
        </div>
      </div>

      {donazioni.length === 0 ? (
        <EmptyState icon={Wallet} title={filter ? "Nessuna donazione corrisponde alla ricerca" : "Nessuna donazione registrata"}
          hint={filter ? "Prova con un altro termine di ricerca." : "Registra la prima donazione: la ricevuta viene numerata automaticamente."}
          action={!filter && <Btn icon={Plus} onClick={onNuova}>Registra donazione</Btn>} />
      ) : (
        <table className="ledger-table">
          <thead>
            <tr><th>Ricevuta</th><th>Data</th><th>Donatore</th><th>Metodo</th><th className="num">Importo</th><th></th></tr>
          </thead>
          <tbody>
            {donazioni.map((d) => (
              <tr key={d.id}>
                <td className="mono">n. {d.numeroRicevuta}</td>
                <td>{fmtDate(d.data)}</td>
                <td>
                  <div className="cell-title">{d.donatoreNome}</div>
                  {d.inMemoriaDi && <div className="cell-sub">in memoria di {d.inMemoriaDi}</div>}
                </td>
                <td>{d.metodoPagamento}</td>
                <td className="num mono">{fmtCurrency(d.importo)}</td>
                <td className="row-actions">
                  <button className="icon-btn" onClick={() => onVediRicevuta(d)}><FileText size={14} /></button>
                  <button className="icon-btn" onClick={() => onModifica(d)}><Pencil size={14} /></button>
                  <button className="icon-btn icon-btn-danger" onClick={() => onElimina(d)}><Trash2 size={14} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function DonazioneForm({ donazione, donatori, donazioni, onClose, onSave }) {
  const [data, setData] = useState(donazione);
  const [salvaInAnagrafica, setSalvaInAnagrafica] = useState(!donazione.donatoreId);
  const set = (k) => (e) => setData({ ...data, [k]: e.target.value });

  const donatoriOrdinati = donatori.slice().sort((a, b) => a.nome.localeCompare(b.nome));
  const ultimoNumero = lastReceiptNumber(donazioni);
  const numeroSuggerito = suggestReceiptNumber(donazioni);

  const [donatoreQuery, setDonatoreQuery] = useState(() => {
    const match = donatori.find((don) => don.id === donazione.donatoreId);
    return match ? match.nome : "";
  });

  const onCercaDonatore = (e) => {
    const val = e.target.value;
    setDonatoreQuery(val);
    const match = donatoriOrdinati.find((don) => don.nome.toLowerCase() === val.trim().toLowerCase());
    if (match) {
      setData({
        ...data, donatoreId: match.id, titolo: match.titolo, donatoreNome: match.nome,
        donatoreIndirizzo: match.indirizzo, donatoreCapComune: match.capComune,
      });
      setSalvaInAnagrafica(true);
    } else if (data.donatoreId) {
      setData({ ...data, donatoreId: "" });
    }
  };

  const valid = data.donatoreNome.trim() && Number(data.importo) > 0 && data.data;

  return (
    <Modal title={donazione.id ? "Modifica donazione" : "Nuova donazione"} onClose={onClose} wide>
      <form className="form-grid" onSubmit={(e) => { e.preventDefault(); if (valid) onSave(data, salvaInAnagrafica); }}>
        {donatoriOrdinati.length > 0 && (
          <Field label="Donatore già in anagrafica (facoltativo)" span>
            <input
              className="input"
              list="donatori-datalist"
              value={donatoreQuery}
              onChange={onCercaDonatore}
              placeholder="Digita le prime lettere del nome per cercarlo…"
              autoComplete="off"
            />
            <datalist id="donatori-datalist">
              {donatoriOrdinati.map((don) => <option key={don.id} value={don.nome} />)}
            </datalist>
          </Field>
        )}

        <Field label="N. ricevuta">
          <input className="input mono" value={data.numeroRicevuta} onChange={set("numeroRicevuta")} placeholder="es. 278" />
          <span className="field-hint">
            {ultimoNumero !== null ? `Ultima registrata: n. ${ultimoNumero} · ` : ""}
            Prossima suggerita: n. {numeroSuggerito}
            {data.numeroRicevuta !== numeroSuggerito && (
              <button type="button" className="field-hint-link" onClick={() => setData({ ...data, numeroRicevuta: numeroSuggerito })}>
                usa questa
              </button>
            )}
          </span>
        </Field>
        <Field label="Data *"><input type="date" className="input" value={data.data} onChange={set("data")} required /></Field>

        <Field label="Titolo">
          <select className="input" value={data.titolo} onChange={set("titolo")}>
            <option value="Signora">Signora</option>
            <option value="Signor">Signor</option>
            <option value="Sig.ra">Sig.ra</option>
            <option value="Sig.">Sig.</option>
            <option value="">(nessuno)</option>
          </select>
        </Field>
        <Field label="Nome e cognome donatore *">
          <input className="input" value={data.donatoreNome} onChange={set("donatoreNome")} required placeholder="es. Abramo Rita" />
        </Field>

        <Field label="Indirizzo donatore"><input className="input" value={data.donatoreIndirizzo} onChange={set("donatoreIndirizzo")} placeholder="es. Via Tridentina, 21" /></Field>
        <Field label="CAP e Comune donatore"><input className="input" value={data.donatoreCapComune} onChange={set("donatoreCapComune")} placeholder="es. 33054 Lignano Sabb. (UD)" /></Field>

        <Field label="Importo (€) *"><input type="number" step="0.01" min="0.01" className="input mono" value={data.importo} onChange={set("importo")} required /></Field>
        <Field label="Pervenuto tramite">
          <select className="input" value={data.metodoPagamento} onChange={set("metodoPagamento")}>
            <option>Contanti</option><option>Bonifico bancario</option><option>Assegno</option><option>Vaglia postale</option><option>Altro</option>
          </select>
        </Field>

        <Field label="In memoria di (facoltativo)" span>
          <input className="input" value={data.inMemoriaDi} onChange={set("inMemoriaDi")} placeholder="es. Romano Zurco" />
        </Field>

        <Field label="Causale — uso interno, non stampata (facoltativo)" span>
          <input className="input" value={data.causale} onChange={set("causale")} placeholder="per classificare la donazione nei report" />
        </Field>
        <Field label="Note interne" span><textarea className="input textarea" value={data.note} onChange={set("note")} rows={2} /></Field>

        <label className="checkbox-field field-span">
          <input type="checkbox" checked={salvaInAnagrafica} onChange={(e) => setSalvaInAnagrafica(e.target.checked)} />
          Salva o aggiorna questo donatore nell'anagrafica, così la prossima volta basta selezionarlo
        </label>

        <div className="modal-actions form-actions">
          <Btn type="button" variant="ghost" onClick={onClose}>Annulla</Btn>
          <Btn type="submit" icon={Check} disabled={!valid}>Salva donazione</Btn>
        </div>
      </form>
    </Modal>
  );
}

