function DonatoriTab({ donatori, totale, filter, setFilter, onNuovo, onModifica, onElimina, onNuovaDonazione, onExport }) {
  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h1>Anagrafica donatori</h1>
          <p className="page-sub">{totale} {totale === 1 ? "donatore salvato" : "donatori salvati"} — utile per chi dona più volte</p>
        </div>
        <div className="page-head-actions">
          <Btn variant="outline" icon={Download} onClick={onExport} disabled={totale === 0}>Esporta Excel</Btn>
          <Btn icon={Plus} onClick={onNuovo}>Nuovo donatore</Btn>
        </div>
      </div>

      <div className="toolbar">
        <div className="search-box">
          <Search size={15} />
          <input placeholder="Cerca per nome, indirizzo, comune…" value={filter} onChange={(e) => setFilter(e.target.value)} />
        </div>
      </div>

      {donatori.length === 0 ? (
        <EmptyState icon={Users} title={filter ? "Nessun donatore corrisponde alla ricerca" : "L'anagrafica donatori è vuota"}
          hint={filter ? "Prova con un altro termine di ricerca." : "Aggiungi qui i donatori abituali: quando registri una donazione potrai richiamarli con un clic invece di riscrivere indirizzo e CAP."}
          action={!filter && <Btn icon={Plus} onClick={onNuovo}>Aggiungi donatore</Btn>} />
      ) : (
        <table className="ledger-table">
          <thead>
            <tr><th>Donatore</th><th>Indirizzo</th><th>Contatti</th><th></th></tr>
          </thead>
          <tbody>
            {donatori.map((don) => (
              <tr key={don.id}>
                <td>
                  <div className="cell-title">{don.titolo ? `${don.titolo} ` : ""}{don.nome}</div>
                  {don.note && <div className="cell-sub">{don.note}</div>}
                </td>
                <td>
                  <div>{don.indirizzo || "—"}</div>
                  <div className="cell-sub">{don.capComune}</div>
                </td>
                <td>
                  <div className="cell-sub">{don.telefono}</div>
                  <div className="cell-sub">{don.email}</div>
                </td>
                <td className="row-actions">
                  <button className="icon-btn" title="Registra donazione" onClick={() => onNuovaDonazione(don)}><UserPlus size={14} /></button>
                  <button className="icon-btn" onClick={() => onModifica(don)}><Pencil size={14} /></button>
                  <button className="icon-btn icon-btn-danger" onClick={() => onElimina(don)}><Trash2 size={14} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

